#include <iostream>

using std::cout;
using std::endl;
using std::cin;

enum ROCK_PAPER_SCISSORS
{
    SCISSORS = 1,
    ROCK,
    PAPER,

    GAME_EXIT
};

int main()
{
    srand(time(NULL));

    int iPlayer, iComputer;
    int iWin = 0, iDraw = 0, iLose = 0;

    while (true)
    {
        cout << "1. 가위  2. 바위  3. 보  4. 게임종료" << endl;
        cout << "메뉴를 입력하세요: ";
        cin >> iPlayer;

        if (iPlayer < SCISSORS || GAME_EXIT < iPlayer)
        {
            cout << "잘못된 값입니다." << endl;
            continue;
        }
        else if (GAME_EXIT == iPlayer)
        {
            break;
        }

        iComputer = rand() % PAPER + SCISSORS;
        cout << "YOU: " << iPlayer << ", COM: " << iComputer << endl;

        switch (iPlayer - iComputer)
        {
        case 1:
        case -2:
            cout << "Win!" << endl;
            iWin++;
            break;
        case 0:
            cout << "Draw!" << endl;
            iDraw++;
            break;
        default:
            cout << "Lose!" << endl;
            iLose++;
            break;
        }
    }

    cout << "전적: " << iWin << "승 " << iDraw << "무 " << iLose << "패" << endl;

    return 0;
}
